import { describe, expect, it } from "vite-plus/test";
import { EnvironmentId, ThreadId } from "@t3tools/contracts";
import { DEFAULT_CLIENT_SETTINGS } from "@t3tools/contracts/settings";
import {
  isNotificationQuietTime,
  notificationAllowed,
  takeNewNotifications,
  type AttentionNotification,
} from "./attentionNotificationPolicy";
const alert: AttentionNotification = {
  key: "env:item:approval",
  revision: 1,
  category: "approval",
  ref: { environmentId: EnvironmentId.make("env"), threadId: ThreadId.make("thread") },
};
const at = (time: string) => new Date(`2026-09-29T${time}:00`);
describe("client notification policy", () => {
  it.each([
    ["21:59", false],
    ["22:00", true],
    ["23:59", true],
    ["00:00", true],
    ["07:59", true],
    ["08:00", false],
  ])("uses local overnight start-inclusive/end-exclusive policy at %s", (time, expected) => {
    expect(isNotificationQuietTime({ enabled: true, start: "22:00", end: "08:00" }, at(time))).toBe(
      expected,
    );
  });
  it("handles daytime intervals, disabled schedules and equal endpoints", () => {
    const schedule = { enabled: true, start: "09:00", end: "17:00" };
    expect(isNotificationQuietTime(schedule, at("09:00"))).toBe(true);
    expect(isNotificationQuietTime(schedule, at("17:00"))).toBe(false);
    expect(isNotificationQuietTime({ ...schedule, end: "09:00" }, at("01:00"))).toBe(true);
    expect(isNotificationQuietTime({ ...schedule, enabled: false }, at("10:00"))).toBe(false);
  });
  it("applies category, environment mute and quiet time without changing attention", () => {
    expect(notificationAllowed(DEFAULT_CLIENT_SETTINGS, alert, at("12:00"))).toBe(true);
    expect(
      notificationAllowed(
        { ...DEFAULT_CLIENT_SETTINGS, notificationCategories: [] },
        alert,
        at("12:00"),
      ),
    ).toBe(false);
    expect(
      notificationAllowed(
        { ...DEFAULT_CLIENT_SETTINGS, notificationMutedEnvironments: [alert.ref.environmentId] },
        alert,
        at("12:00"),
      ),
    ).toBe(false);
    expect(
      notificationAllowed(
        {
          ...DEFAULT_CLIENT_SETTINGS,
          notificationQuietHours: { enabled: true, start: "22:00", end: "08:00" },
        },
        alert,
        at("23:00"),
      ),
    ).toBe(false);
    expect(
      notificationAllowed(
        DEFAULT_CLIENT_SETTINGS,
        { ...alert, category: "disconnect" },
        at("12:00"),
      ),
    ).toBe(false);
  });
  it("deduplicates scoped material revisions independently for two clients and consumes suppressed observations", () => {
    const first = takeNewNotifications(new Map(), [alert]);
    expect(first.alerts).toEqual([alert]);
    expect(takeNewNotifications(first.observed, [alert]).alerts).toEqual([]);
    expect(takeNewNotifications(new Map(), [alert]).alerts).toEqual([alert]);
    const newer = { ...alert, revision: 2 };
    const next = takeNewNotifications(first.observed, [newer]);
    expect(next.alerts).toEqual([newer]);
    expect(takeNewNotifications(next.observed, [alert]).alerts).toEqual([]);
    const other = {
      ...alert,
      key: "other:item:approval",
      ref: { ...alert.ref, environmentId: EnvironmentId.make("other") },
    };
    expect(takeNewNotifications(next.observed, [newer, other]).alerts).toEqual([other]);
  });
});

import type { EnvironmentId, ScopedThreadRef } from "@t3tools/contracts";
import type { ClientSettings } from "@t3tools/contracts/settings";
import type { EnvironmentAttentionState } from "@t3tools/client-runtime/state/attention";
import { scopeThreadRef } from "@t3tools/client-runtime/environment";

export type NotificationCategory = ClientSettings["notificationCategories"][number];
export interface AttentionNotification {
  readonly key: string;
  readonly revision: number | string;
  readonly category: NotificationCategory;
  readonly ref: ScopedThreadRef;
  readonly turnId?: string | null;
}
export const NOTIFICATION_CATEGORIES = {
  approval: "Approval needed",
  user_input: "Input needed",
  failure: "Thread failed",
  disconnect: "Provider disconnected",
  completion: "Thread completed",
} satisfies Record<NotificationCategory, string>;

export function isNotificationQuietTime(
  quiet: ClientSettings["notificationQuietHours"],
  now: Date,
) {
  if (!quiet.enabled) return false;
  const minutes = (time: string) => Number(time.slice(0, 2)) * 60 + Number(time.slice(3));
  const start = minutes(quiet.start);
  const end = minutes(quiet.end);
  const current = now.getHours() * 60 + now.getMinutes();
  return (
    start === end ||
    (start < end ? current >= start && current < end : current >= start || current < end)
  );
}

export function notificationAllowed(
  settings: ClientSettings,
  alert: AttentionNotification,
  now: Date,
) {
  return (
    settings.notificationCategories.includes(alert.category) &&
    !settings.notificationMutedEnvironments.includes(alert.ref.environmentId) &&
    !isNotificationQuietTime(settings.notificationQuietHours, now)
  );
}

export function canonicalNotificationCandidates(
  environmentId: EnvironmentId,
  state: EnvironmentAttentionState,
): AttentionNotification[] {
  if (state.status !== "live" || !state.notificationCandidates) return [];
  const alerts: AttentionNotification[] = [];
  for (const [, { entity }] of state.notificationCandidates) {
    if (!entity) continue;
    const ref = scopeThreadRef(environmentId, entity.value.threadId);
    if (entity.type === "item" && entity.value.status === "open") {
      alerts.push({
        key: `${environmentId}:${entity.value.attentionId}:${entity.value.kind}`,
        revision: entity.value.revision,
        category: entity.value.kind,
        ref,
        turnId: entity.value.turnId,
      });
    } else if (
      entity.type === "summary" &&
      entity.value.phase === "completed" &&
      entity.value.turnId !== null
    ) {
      alerts.push({
        key: `${environmentId}:${entity.value.threadId}:completion`,
        revision: entity.value.turnId,
        category: "completion",
        ref,
        turnId: entity.value.turnId,
      });
    }
  }
  return alerts;
}

/** Observations advance even while muted, quiet or disabled: opting in never replays them. */
export function takeNewNotifications(
  observed: Map<string, string | number>,
  candidates: ReadonlyArray<AttentionNotification>,
) {
  const next = new Map<string, string | number>();
  const alerts: AttentionNotification[] = [];
  for (const candidate of candidates) {
    const old = observed.get(candidate.key);
    const newer =
      typeof old === "number" && typeof candidate.revision === "number"
        ? candidate.revision > old
        : old !== candidate.revision;
    next.set(
      candidate.key,
      typeof old === "number" && typeof candidate.revision === "number"
        ? Math.max(old, candidate.revision)
        : candidate.revision,
    );
    if (newer) alerts.push(candidate);
  }
  return { observed: next, alerts };
}

